-- reserve_offline_numbers(p_device_id text, p_size integer)
CREATE OR REPLACE FUNCTION public.reserve_offline_numbers(p_device_id text, p_size integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tenant uuid := public.app_current_tenant_id();
  v_staff  uuid := public.app_actor_staff_id();
  v_size   int  := LEAST(GREATEST(COALESCE(p_size, 20), 1), 100);
  v_order  bigint;
  v_inv    bigint;
  v_id     uuid;
BEGIN
  IF v_tenant IS NULL OR v_staff IS NULL THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  IF NOT public.app_has_permission('payments.collect') THEN
    RAISE EXCEPTION 'لا تملك صلاحية البيع' USING ERRCODE = '42501';
  END IF;
  IF p_device_id IS NULL OR length(p_device_id) NOT BETWEEN 8 AND 64 THEN
    RAISE EXCEPTION 'معرّف الجهاز غير صالح' USING ERRCODE = '22023';
  END IF;
  -- At most 10 blocks a day per shop: a runaway client cannot burn the numbering.
  IF (SELECT count(*) FROM public.offline_number_blocks WHERE tenant_id = v_tenant AND created_at > now() - interval '1 day') >= 10 THEN
    RAISE EXCEPTION 'تجاوزت حد الأرقام المحجوزة اليوم' USING ERRCODE = '22023';
  END IF;

  INSERT INTO public.tenant_order_counters (tenant_id) VALUES (v_tenant) ON CONFLICT (tenant_id) DO NOTHING;
  UPDATE public.tenant_order_counters
     SET next_order_number = next_order_number + v_size,
         next_invoice_number = next_invoice_number + v_size
   WHERE tenant_id = v_tenant
  RETURNING next_order_number - v_size, next_invoice_number - v_size INTO v_order, v_inv;

  INSERT INTO public.offline_number_blocks (tenant_id, device_id, staff_id, order_from, invoice_from, size)
  VALUES (v_tenant, p_device_id, v_staff, v_order, v_inv, v_size)
  RETURNING id INTO v_id;
  RETURN jsonb_build_object('block_id', v_id, 'order_from', v_order, 'invoice_from', v_inv, 'size', v_size);
END;
$function$;
